// Changes: The grammar module – definition text (N, T, S) + rules text (P) in, one analysed G = (N, T, P, S) out.
//          N, T and S are decided here once; the formal definition, its checks, the LL table and the exports all
//          read them from the result instead of deciding them again.

import { parseDecls, type SymbolDecl } from './definition'
import { analyzeLL, llProblems, parseGrammar, type LLAnalysis, type Problem, type Rule } from './grammar'

/** The texts the grammar is written in (the Definition tab). */
export interface GrammarSource {
  /** Rules P, one per line. */
  rules: string
  /** Declared N and T, one symbol per line with an optional note. */
  nonterminals: string
  terminals: string
  /** Chosen start symbol, '' = left side of the first rule. */
  start: string
}

export interface Grammar {
  /** Effective nonterminals – declared ones and every left side of P, S first. */
  N: string[]
  /** Effective terminals – declared ones and every right-side symbol that is not in N. */
  T: string[]
  /** Effective start symbol – the chosen one when it is in N, otherwise the left side of the first rule. */
  S: string
  rules: Rule[]
  /** Syntax errors of P. */
  errors: string[]
  /** Notes from the N/T declarations. */
  notes: Map<string, string>
  /** N or T is declared (otherwise both are derived from P). */
  declared: boolean
  /** Symbols of P missing from the declarations ("Doplniť z pravidiel"). */
  missingN: string[]
  missingT: string[]
  /** LL(1) analysis – null without rules. */
  ll: LLAnalysis | null
  problems: { definition: Problem[]; ll: Problem[] }
}

const uniq = (xs: string[]) => [...new Set(xs)]

export function analyzeGrammar(src: GrammarSource): Grammar {
  const { rules, errors } = parseGrammar(src.rules)
  const nDecl = parseDecls(src.nonterminals)
  const tDecl = parseDecls(src.terminals)
  const declN = uniq(nDecl.map((d) => d.symbol))
  const declT = uniq(tDecl.map((d) => d.symbol))
  const start = src.start.trim()

  // One rule for G: a symbol with rules is a nonterminal, everything else used or declared as a terminal is in T.
  const lhs = uniq(rules.map((r) => r.lhs))
  const allN = uniq([...declN, ...lhs])
  const S = start && allN.includes(start) ? start : (rules[0]?.lhs ?? allN[0] ?? '')
  const N = S ? [S, ...allN.filter((n) => n !== S)] : allN
  const isN = new Set(N)
  const T = uniq([...declT, ...rules.flatMap((r) => r.rhs)]).filter((t) => !isN.has(t))

  const ll = rules.length ? analyzeLL(rules, { N, T }) : null

  const notes = new Map<string, string>()
  ;[...nDecl, ...tDecl].forEach((d) => d.note && !notes.has(d.symbol) && notes.set(d.symbol, d.note))

  const def = checkDefinition({ rules, errors, nDecl, tDecl, start, N, T, S })
  return { N, T, S, rules, errors, notes, ...def, ll, problems: { definition: def.problems, ll: llProblems(errors, ll) } }
}

// Consistency of the declared N, T and S with the rules P (the Kontrola panel of the Definition tab).
function checkDefinition(g: {
  rules: Rule[]
  errors: string[]
  nDecl: SymbolDecl[]
  tDecl: SymbolDecl[]
  start: string
  N: string[]
  T: string[]
  S: string
}) {
  const { rules, start, S } = g
  const declN = uniq(g.nDecl.map((d) => d.symbol))
  const declT = uniq(g.tDecl.map((d) => d.symbol))
  const inN = new Set(declN)
  const inT = new Set(declT)
  const declared = declN.length > 0 || declT.length > 0
  const isLhs = new Set(rules.map((r) => r.lhs))
  const lhs = [...isLhs]
  const used = uniq(rules.flatMap((r) => r.rhs))

  const missingN = lhs.filter((s) => !inN.has(s) && !inT.has(s))
  const missingT = used.filter((s) => !isLhs.has(s) && !inN.has(s) && !inT.has(s))

  const probs: Problem[] = g.errors.map((text) => ({ level: 'bad', text }))
  const bad = (text: string) => probs.push({ level: 'bad', text })
  const warn = (text: string) => probs.push({ level: 'warn', text })
  const info = (text: string) => probs.push({ level: 'info', text })

  const dupes = (decls: SymbolDecl[], set: string) => {
    const seen = new Map<string, number>()
    decls.forEach((d) => {
      if (seen.has(d.symbol)) warn(`${d.symbol} je v ${set} dvakrát (riadky ${seen.get(d.symbol)} a ${d.line})`)
      else seen.set(d.symbol, d.line)
    })
  }
  dupes(g.nDecl, 'N')
  dupes(g.tDecl, 'T')
  declN.filter((s) => inT.has(s)).forEach((s) => bad(`${s} je v N aj v T – musí platiť N ∩ T = ∅`))

  if (!rules.length && !g.errors.length) info('P je prázdna – zatiaľ žiadne pravidlá.')

  if (!start) {
    if (rules.length) info(`S nie je zadaný – použije sa ľavá strana prvého pravidla (${S}).`)
  } else if (!g.N.includes(start)) {
    bad(S ? `S = ${start} nie je v N – použije sa ${S}` : `S = ${start} nie je v N`)
  } else if (rules.length && !isLhs.has(start)) {
    bad(`S = ${start} nemá v P žiadne pravidlo`)
  }

  if (declared) {
    missingN.forEach((s) => bad(`${s} je na ľavej strane pravidla, ale nie je v N`))
    lhs.filter((s) => inT.has(s) && !inN.has(s)).forEach((s) => bad(`${s} je v T, ale je na ľavej strane pravidla (A → x vyžaduje A ∈ N)`))
    missingT.forEach((s) => {
      const r = rules.findIndex((x) => x.rhs.includes(s))
      bad(`Symbol ${s} (pravidlo ${r + 1}) nie je v N ani v T – x ∈ (N ∪ T)*`)
    })
    if (rules.length) {
      declN.filter((s) => !isLhs.has(s)).forEach((s) => warn(`${s} je v N, ale nemá v P žiadne pravidlo (prázdny riadok LL tabuľky)`))
      declT.filter((s) => !used.includes(s)).forEach((s) => info(`Terminál ${s} sa v P nepoužíva`))
    }
  } else if (rules.length) {
    info('N a T nie sú deklarované – odvodzujú sa z pravidiel. „Doplniť z pravidiel“ ich vypíše.')
  }

  if (declared && !probs.some((p) => p.level === 'bad')) {
    probs.unshift({ level: 'ok', text: `G = (N, T, P, S) je konzistentná: |N| = ${g.N.length}, |T| = ${g.T.length}, |P| = ${rules.length}, S = ${S || '–'}` })
  }

  return { declared, missingN, missingT, problems: probs }
}
